; Hand-written x64 assembly (MASM): tic-tac-toe as a finite-state machine. The computer never
; calculates a move and never even looks at the board to choose one. Every position it can face was
; solved ahead of time (by ../csharp-lookup-table/GenTable.cs --state-machine) and numbered; the
; program just carries a state number. On its turn it reads that state's set of best moves, picks
; one at random and steps to the state for that move; after the human's reply it steps to the next
; state through a table. The bitboards are kept only to draw the board and to detect the end of the
; game. No C runtime and no .NET: it talks to Windows through kernel32 only.
;
;   buildasm.ps1 builds it, or by hand from an x64 Native Tools prompt:
;     ml64 /nologo /c /Fo TicTacToeAsmStates.obj TicTacToeStates.asm
;     link /nologo /SUBSYSTEM:CONSOLE /ENTRY:main /NODEFAULTLIB /OUT:TicTacToeAsmStates.exe TicTacToeAsmStates.obj kernel32.lib
;
; Conventions: Win64 (rcx, rdx, r8, r9; rbx rsi rdi r12-r15 preserved). Squares are 9-bit masks,
; bit i = square i+1.
;   cstates[s]            = first human state << 9 | set of best moves   (computer to move in s)
;   human state for move m = first human state + number of best moves below m
;   cnext[human * 9 + r]  = state after the human replies on square r, or 0FFFFh if the game ended
; HSTART is the extra human state used when the human moves first (its replies are the openings).
; Conventions: Win64 (rcx, rdx, r8, r9; rbx rsi rdi r12-r15 preserved). Positions are two 9-bit
; masks, bit i = square i+1. Each table entry packs (human | computer << 9) << 9 | best moves.

